/** What reached the wire, in a form that does not depend on how it was built. */
function wire([url, init = {}]: [string, RequestInit?]) {
  const headers = Object.fromEntries(
    [...new Headers(init.headers).entries()].sort(([a], [b]) => a.localeCompare(b)),
  );
  const body = init.body instanceof FormData ? `FormData(${[...init.body.keys()].join(",")})` : (init.body ?? null);
  return {
    url,
    method: init.method ?? "GET",
    headers,
    body,
    credentials: init.credentials ?? null,
    cache: init.cache ?? null,
  };
}

async function observe(call: () => Promise<unknown>, answer: Answer, token: string | null) {
  vi.mocked(getAuthToken).mockResolvedValue(token);
  const fetchMock = vi.fn(async () =>
    new Response(answer.json === undefined ? "oops" : JSON.stringify(answer.json), { status: answer.status }),
  );
  vi.stubGlobal("fetch", fetchMock);
  const result = await call();
  return {
    requests: (fetchMock.mock.calls as unknown as [string, RequestInit?][]).map(wire),
    result: JSON.parse(JSON.stringify(result ?? null)),
  };
}

const GOLDEN_PATH = "src/services/api/glueContracts.golden.json";

afterEach(() => vi.unstubAllGlobals());

describe("the service clients send and answer what they always did", () => {
  const golden = JSON.parse(readFileSync(GOLDEN_PATH, "utf8")) as Record<string, unknown>;
  for (const [name, call, answer] of CASES) {
    it(name, async () => {
      const observed = {
        signedIn: await observe(call, answer, "tok"),
        signedOut: await observe(call, answer, null),
      };
      expect(observed).toEqual(golden[name]);
    });
  }
});
